using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// Shared free mode art (ground, path, scenery, UI). Lives at Resources/ArtLibrary.
/// Building and resource art lives on their own definitions (the icon field).
/// The defaults are generated by Tools > Age of Stickman > Generate Placeholder Art;
/// replace any sprite here with hand-made art and the game uses it.
/// </summary>
[CreateAssetMenu(fileName = "ArtLibrary", menuName = "Age of Stickman/Art Library")]
public class ArtLibrary : ScriptableObject
{
    public const string ResourcePath = "ArtLibrary";

    [Header("World")]
    public Sprite grassTile;
    public Sprite settlementTile;
    public Sprite pathTile;
    public Sprite waterTile;
    public Sprite hillTile;
    [Header("Terrain (smooth edges)")]
    [Tooltip("Plain ground variants, scattered at random. The first is the most common.")]
    public List<Sprite> grassVariants = new List<Sprite>();

    [Tooltip("16 hill shapes, by which corners are hill (1 = bottom-left, 2 = bottom-right, 4 = top-left, 8 = top-right). Drawn half a tile offset.")]
    public List<Sprite> hillShapes = new List<Sprite>();

    [Tooltip("Hill tiers 2 and 3 (same corner order): drawn over the middle of large hill areas for height.")]
    public List<Sprite> hillShapes2 = new List<Sprite>();
    public List<Sprite> hillShapes3 = new List<Sprite>();

    [Tooltip("Extra versions of the all-hill shape, scattered at random.")]
    public List<Sprite> hillFullVariants = new List<Sprite>();

    [Tooltip("Water: 16 shapes (same corner order as hills), each with waterFrameCount animation frames in a row.")]
    public List<Sprite> waterFrames = new List<Sprite>();
    public int waterFrameCount = 6;
    public float waterFps = 3f;

    [Tooltip("Material for the water layer (adds moving ripples). Optional.")]
    public Material waterMaterial;

    public List<Sprite> trees = new List<Sprite>();
    public List<Sprite> rocks = new List<Sprite>();
    public List<Sprite> bushes = new List<Sprite>();

    [Header("Villagers (ambient life)")]
    public Sprite villagerIdle;
    public List<Sprite> villagerWalk = new List<Sprite>();
    public List<Sprite> villagerWork = new List<Sprite>();

    [Header("Buildings")]
    public Sprite scaffold;
    public Sprite rallyFlag;

    [Header("UI")]
    [Tooltip("9-sliced rounded rectangle used for panels and buttons.")]
    public Sprite panel;
    public Sprite peopleIcon;
    public Sprite enemyIcon;

    [Header("Raider camps")]
    [Tooltip("Animated frames of a raider camp (3x3 tiles, pivot on the footprint corner).")]
    public List<Sprite> campFrames = new List<Sprite>();

    [Tooltip("Camp pieces, each on the same 3x3 canvas, sorted separately so units can walk between them.")]
    public Sprite campGround, campBackTent, campFrontTent, campLoot;
    public List<Sprite> campBanner = new List<Sprite>();
    public List<Sprite> campFire = new List<Sprite>();
    [Tooltip("A burnt-out camp: scorched ground, charred tent frames, smouldering embers; and the flames while it burns.")]
    public Sprite campBurntGround, campBurntBackTent, campBurntFrontTent;
    public List<Sprite> campEmbers = new List<Sprite>();
    public List<Sprite> campBlazeBack = new List<Sprite>();
    public List<Sprite> campBlazeFront = new List<Sprite>();
    public Sprite researchIcon;

    [Header("Wild sites")]
    public Sprite siteRuins, siteRuinsLooted, siteDungeon, siteDungeonSealed, siteShrine, siteShrineUsed;
    public Sprite siteCache, siteCaravan, siteLoreStone, siteLoreStoneRead;
    [Tooltip("Wolf den, spider nest, troll cave.")]
    public List<Sprite> siteLairs = new List<Sprite>();
    [Tooltip("Ground tiles for each biome after Temperate, five each in Biome order (Desert, Tundra, Swamp, Volcanic, Crystal).")]
    public List<Sprite> biomeGround = new List<Sprite>();
    [Tooltip("Trees for each biome after Temperate, two each in Biome order.")]
    public List<Sprite> biomeTrees = new List<Sprite>();
    [Tooltip("Berry bushes for each biome after Temperate, one each in Biome order.")]
    public List<Sprite> biomeBushes = new List<Sprite>();

    [Tooltip("Rich vein sites, one per deposit id in siteVeinIds.")]
    public List<Sprite> siteVeins = new List<Sprite>();
    public List<string> siteVeinIds = new List<string>();

    [Tooltip("Map icons, by SiteKind.")]
    public List<Sprite> siteIcons = new List<Sprite>();


    private static ArtLibrary cached;

    public static ArtLibrary Load()
    {
        if (cached == null)
        {
            cached = Resources.Load<ArtLibrary>(ResourcePath);
        }
        return cached;
    }
}
